-- Normalized sub-dimensions
CREATE TABLE DimCategory (
    CategoryKey INT PRIMARY KEY,
    CategoryName NVARCHAR(100) NOT NULL
);

CREATE TABLE DimSubcategory (
    SubcategoryKey INT PRIMARY KEY,
    SubcategoryName NVARCHAR(100) NOT NULL,
    CategoryKey INT NOT NULL,
    CONSTRAINT FK_DimSubcategory_Category FOREIGN KEY (CategoryKey) REFERENCES DimCategory(CategoryKey)
);

CREATE TABLE DimBrand (
    BrandKey INT PRIMARY KEY,
    BrandName NVARCHAR(100) NOT NULL,
    BrandCountry NVARCHAR(100)
);

-- Product dimension now references normalized tables
CREATE TABLE DimProduct (
    ProductKey INT PRIMARY KEY,
    ProductName NVARCHAR(200) NOT NULL,
    ListPrice DECIMAL(10,2),
    SubcategoryKey INT NOT NULL,
    BrandKey INT NOT NULL,
    CONSTRAINT FK_DimProduct_Subcategory FOREIGN KEY (SubcategoryKey) REFERENCES DimSubcategory(SubcategoryKey),
    CONSTRAINT FK_DimProduct_Brand FOREIGN KEY (BrandKey) REFERENCES DimBrand(BrandKey)
);
